const raw = $input.first().json;
const input = (raw && raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

const eventType = input.event_type || 'prevention.reminder_eligible';
const violations = [];
let isEligible = true;

// 1. Verificación de aprobación clínica por veterinario
if (input.plan_status && !['APPROVED', 'ACTIVE'].includes(input.plan_status)) {
  violations.push('Plan no aprobado formalmente por médico veterinario (' + input.plan_status + ')');
  isEligible = false;
}

// 2. Verificación de vigencia y datos desactualizados
if (input.is_stale === true || input.confidence_status === 'STALE') {
  violations.push('Registro preventivo desactualizado (STALE) requiere revalidación humana');
  isEligible = false;
}

// 3. Verificación de conflicto de registros
if (input.conflict_status === 'CONFLICT_DETECTED') {
  violations.push('Conflicto detectado en registro preventivo requiere auditoría');
  isEligible = false;
}

// 4. Verificación de duelo
if (input.is_bereaved === true) {
  violations.push('Paciente en protocolo de duelo / fallecimiento reciente');
  isEligible = false;
}

// 5. Consentimiento y permisos de cuidador
if (input.has_consent !== true) {
  violations.push('Falta consentimiento expreso para comunicaciones preventivas');
  isEligible = false;
}
if (input.caregiver_revoked === true) {
  violations.push('Permiso de cuidador revocado');
  isEligible = false;
}

// 6. Límite de frecuencia
if (input.frequency_cap_exceeded === true) {
  violations.push('Límite de frecuencia de contacto alcanzado');
  isEligible = false;
}

let templateCode = 'vet_preventive_due_date_reminder';
let alertSummary = '';

switch (eventType) {
  case 'prevention.plan_approved':
    templateCode = 'vet_preventive_plan_welcome';
    alertSummary = 'Plan preventivo individualizado aprobado por médico veterinario para ' + (input.pet_name || 'paciente') + '.';
    break;
  case 'prevention.due_item_verified':
  case 'prevention.reminder_eligible':
    templateCode = 'vet_preventive_due_date_reminder';
    alertSummary = 'Recordatorio preventivo: Próximo control de ' + (input.prevention_type || 'salud') + ' para ' + (input.pet_name || 'mascota') + ' (Vence: ' + (input.due_date || 'pronto') + ').';
    break;
  case 'prevention.appointment_requested':
    templateCode = 'vet_preventive_request_received';
    alertSummary = 'Solicitud de cita preventiva recibida para ' + (input.pet_name || 'mascota') + ' (' + (input.prevention_type || '') + ').';
    break;
  case 'prevention.application_verified':
    templateCode = 'vet_preventive_application_confirmed';
    alertSummary = 'Aplicación preventiva verificada por médico veterinario para ' + (input.pet_name || 'mascota') + '.';
    break;
  default:
    alertSummary = 'Evento preventivo: ' + eventType + ' procesado para ' + (input.pet_name || 'paciente') + '.';
}

return {
  json: {
    event_type: eventType,
    due_date_id: input.due_date_id || 'prev-due-default',
    plan_id: input.plan_id || 'prev-plan-default',
    prevention_type: input.prevention_type || 'CONTROL_PREVENTIVO',
    due_date: input.due_date || '2026-11-28',
    client_name: input.client_name || 'Tutor Vet Life',
    client_phone: input.client_phone || '+573132223344',
    pet_name: input.pet_name || 'Paciente',
    is_eligible: isEligible,
    suppression_reasons: violations,
    template_code: templateCode,
    alert_summary: alertSummary,
    send_enabled: false,
    evaluated_at: new Date().toISOString()
  }
};
